{
  "title": "Tax filing, product viability, and design decisions",
  "topics": [
    {
      "id": "tax-filing-process",
      "title": "Tax filing process and related constraints",
      "claims": [
        {
          "text": "Aunt Sveta helped correctly refile tax declarations for about 1000 UAH, avoiding larger fines.",
          "evidence": [1]
        },
        {
          "text": "Filing tax declarations using Excel typically takes about one hour per day, roughly one day per month.",
          "evidence": [5, 6]
        },
        {
          "text": "Correctly matching columns and numbers in declarations is more critical than tax calculation accuracy.",
          "evidence": [8]
        },
        {
          "text": "Quarterly tax reports are required and must be paid correctly.",
          "evidence": [7]
        },
        {
          "text": "The domain for the project has not been purchased.",
          "evidence": [2]
        },
        {
          "text": "The FOP calculator app only supports Ukrainian hryvnia (UAH) accounts; other currencies require daily conversion.",
          "evidence": [19]
        },
        {
          "text": "A minimum of ten users willing to pay 299 UAH is needed for the project to be viable.",
          "evidence": [20]
        }
      ]
    },
    {
      "id": "platform-profitability",
      "title": "Profitability of web vs mobile platforms",
      "claims": [
        {
          "text": "Web platforms are simpler to develop but significantly less profitable than Android/iOS apps.",
          "evidence": [11]
        },
        {
          "text": "Website SEO is poor; the site does not appear even on the 10th page of Google search.",
          "evidence": [11]
        },
        {
          "text": "The website receives no external traffic from Instagram, Threads, or contextual ads.",
          "evidence": [11]
        },
        {
          "text": "App stores (Play Market/App Store) promote new apps, providing visibility for a week.",
          "evidence": [11]
        },
        {
          "text": "There is no passive ad revenue from the website.",
          "evidence": [11]
        },
        {
          "text": "User retention after encountering the paywall is near zero, as users do not wait to access content.",
          "evidence": [11]
        },
        {
          "text": "Conversion rates are assumed to be zero because the product does not simplify user tasks nor integrate with banks or tax cabinets.",
          "evidence": [11]
        }
      ]
    },
    {
      "id": "product-development",
      "title": "Product development strategy and market outlook",
      "claims": [
        {
          "text": "A rapid delivery timeframe of less than a week is targeted for new releases.",
          "evidence": [12]
        },
        {
          "text": "Flutter is chosen as the cross‑platform stack for quick development.",
          "evidence": [12]
        },
        {
          "text": "The application is designed as a local‑first web app, fetching USD/UAH rates every five minutes and performing calculations in the browser.",
          "evidence": [29]
        },
        {
          "text": "The product price is set at 299 UAH, with a 100 % discount code offered via a promo mechanism.",
          "evidence": [20]
        },
        {
          "text": "The project is described as a free “vibe‑code” experiment with little commercial intention.",
          "evidence": [30]
        },
        {
          "text": "It is unlikely that the product will attract any buyers within months.",
          "evidence": [17]
        },
        {
          "text": "The proportion of technical, managerial, and sales posts on LinkedIn has dropped below 50 %.",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "security",
      "title": "Password handling and security considerations",
      "claims": [
        {
          "text": "The discount password is bundled within the application package.",
          "evidence": [23]
        },
        {
          "text": "The password is stored in local storage as a promotional 100 % discount code.",
          "evidence": [20]
        },
        {
          "text": "Most LinkedIn users would be able to hack the app and retrieve the password.",
          "evidence": [28]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "Use Flutter as the cross‑platform development framework to achieve delivery in under a week.",
      "evidence": [12]
    },
    {
      "text": "Design the application as a local‑first web app with in‑browser calculations and exchange‑rate updates every five minutes.",
      "evidence": [29]
    },
    {
      "text": "Set the product price at 299 UAH and provide a 100 % discount code stored locally, effectively making the app free for those who discover it.",
      "evidence": [20]
    },
    {
      "text": "Limit the calculator to UAH (Ukrainian hryvnia) FOP accounts, requiring manual conversion for other currencies.",
      "evidence": [19]
    },
    {
      "text": "Do not purchase a domain at this stage.",
      "evidence": [2]
    }
  ],
  "openQuestions": [
    {
      "text": "Where is the source code located, and can the password be found by searching the code?",
      "evidence": [21]
    }
  ]
}
